public class Ticket {
    private static int nextNumber = 1;   // shared by all tickets
    private final int number;            // one per ticket

    public Ticket() {
        number = nextNumber++;
    }

    public int getNumber() {
        return number;
    }

    public static int issued() {
        return nextNumber - 1;
    }

    public static void main(String[] args) {
        Ticket first = new Ticket();
        Ticket second = new Ticket();
        System.out.println(first.getNumber() + " " + second.getNumber());
        System.out.println("Issued: " + Ticket.issued());
    }
}
